import { createGame, legalMoves, applyMove, status } from '/Users/leonchan/WorkSpace/IDX-Tic-Tac-Toe/src/engine.js';

let terminals = 0, draws = 0, maxLen = 0, lineAt9 = 0, bad = [];
function walk(state, depth) {
  const s = status(state);
  const moves = legalMoves(state);
  if (s.over) {
    terminals++;
    if (s.winner === null) { draws++; bad.push('draw'); }
    if (moves.length !== 0) bad.push('terminal with moves');
    maxLen = Math.max(maxLen, s.moveCount);
    return;
  }
  if (moves.length === 0) bad.push('non-terminal no moves');
  for (const m of moves) {
    const next = applyMove(state, m);
    if (next === state) bad.push('same state');
    walk(next, depth+1);
  }
}
walk(createGame(), 0);
console.log({terminals, draws, maxLen, bad: bad.slice(0,5)});
```

